using System;using System.IO;using System.Linq;using SargasPC;
class NativeAcceptance {
 [STAThread]static int Main(string[] args){if(Environment.OSVersion.Platform!=PlatformID.Win32NT){Console.WriteLine("NOT RUN: native Windows required.");return 2;}string root=Path.Combine(Path.GetTempPath(),"sargon-native-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
 var c=new Core(Path.Combine(root,"profile"));Console.CancelKeyPress+=(s,e)=>{e.Cancel=true;c.Cancelled=true;};string path=Path.Combine(root,"neutral-original.txt");File.WriteAllText(path,"SARGON native DPAPI and handle-isolation acceptance fixture. No malware.");byte[] original=File.ReadAllBytes(path);var w=c.Scan(path);c.Isolate(w,false);if(!File.Exists(path))throw new Exception("Copy-only action removed original");var first=c.Vault().Single();string restored=Path.Combine(root,"restored-copy.txt");c.Restore(first,restored);if(!File.ReadAllBytes(restored).SequenceEqual(original))throw new Exception("DPAPI restore mismatch");bool overwriteBlocked=false;try{c.Restore(first,restored);}catch(IOException){overwriteBlocked=true;}if(!overwriteBlocked)throw new Exception("Existing restore destination not protected");c.Reset();w=c.Scan(path);string result=c.IsolateAndConfirm(w);if(File.Exists(path)||c.VisualEvent!="REMOVAL_CONFIRMED")throw new Exception("Handle-based original removal not confirmed");if(!c.Vault().Any())throw new Exception("Recoverable copy missing");Console.WriteLine("PASS: native DPAPI copy/readback/restore, no-overwrite and verified handle removal on OWN NEUTRAL TEST FILE. This is not a virus-removal efficacy test.");
 if(Array.IndexOf(args,"--readiness")>=0){c.Reset();c.EngineBinaryDirectory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"SARGONService","engine","clamav-1.4.6.win.x64");c.EngineDatabaseDirectory=SharedEngine.DatabasePath();Console.WriteLine(c.TestLocalEngineReadiness());}
 if(Array.IndexOf(args,"--detection")>=0){c.Reset();c.EngineBinaryDirectory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"SARGONService","engine","clamav-1.4.6.win.x64");c.EngineDatabaseDirectory=SharedEngine.DatabasePath();Console.WriteLine(c.TestLocalEngineDetection());}
 return 0;
 }catch(Exception e){Console.WriteLine("NOT CONFIRMED: "+Data.Diagnostic(e));return 1;}finally{try{foreach(string p in Directory.EnumerateFileSystemEntries(root,"*",SearchOption.AllDirectories))FolderMonitor.NoLinks(p);Directory.Delete(root,true);}catch{Console.WriteLine("Cleanup incomplete: inspect own test directory "+root);}}}
}
